package com.zerostreams.app;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;
public class TspSearchTest {
 JSONObject row(String hash,String name,int seeds)throws Exception{return new JSONObject().put("name",name).put("infohash",hash).put("magnet","magnet:?xt=urn:btih:"+hash).put("seeders",seeds).put("leechers",1).put("measured",true).put("sources",new JSONArray().put("one").put("two")).put("category","video");}
 @Test public void rankingRejectsWrongTitleYearEpisodeAndDeadOrSuspectSwarms()throws Exception{String h="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";JSONObject good=row(h,"Fixture.Movie.1999.1080p.x264",80);JSONArray all=new JSONArray().put(good).put(good).put(row(h,"Wrong.Movie.1999",80)).put(row(h,"Fixture.Movie.2000",80)).put(row(h,"Fixture.Movie.1999",0)).put(row(h,"Fixture.Movie.1999",80).put("suspect",true));JSONArray r=TspSearchProvider.rank(all,"Fixture Movie",1999,"movie","550",1,1,3,60);assertEquals(1,r.length());assertEquals("H264",r.getJSONObject(0).getString("codec"));assertEquals("1080p",r.getJSONObject(0).getString("resolution"));assertEquals(0,TspSearchProvider.rank(new JSONArray().put(row(h,"Fixture Movie S01E02",80)),"Fixture Movie",1999,"tv","550",1,3,3,60).length());}
 @Test public void urlMustBeHttpsAndExcludeEmbeddedSecrets()throws Exception{assertEquals("https://api.tspsearch.dev",TspSearchProvider.server("https://api.tspsearch.dev/"));for(String s:new String[]{"http://api.tspsearch.dev","https://user:pass@api.tspsearch.dev","https://api.tspsearch.dev?key=secret"}){try{TspSearchProvider.server(s);fail("Unsafe URL accepted");}catch(java.io.IOException expected){}}}
}
